from __future__ import annotations

import hashlib
import json
from datetime import UTC, datetime, timedelta
from typing import Any

from packages.common.pg_native import PostgresMigration, apply_schema_migrations, connect_postgres
from .models import MarketObservation

SCHEMA_SQL="""
CREATE TABLE IF NOT EXISTS predict_market_observations(market_id text PRIMARY KEY,category_id text NOT NULL,category_title text NOT NULL,category_slug text NOT NULL,category_published_at text,starts_at text,ends_at text,market_created_at text,question text NOT NULL,market_variant text NOT NULL,market_status text NOT NULL,trading_status text NOT NULL,market_url text NOT NULL,filter_reason text,first_seen_at text NOT NULL,last_seen_at text NOT NULL,from_baseline boolean NOT NULL,candidate_at text);
CREATE INDEX IF NOT EXISTS idx_predict_market_candidate ON predict_market_observations(candidate_at DESC);
CREATE INDEX IF NOT EXISTS idx_predict_market_start ON predict_market_observations(starts_at);
CREATE TABLE IF NOT EXISTS predict_market_scan_runs(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,started_at text NOT NULL,completed_at text NOT NULL,status text NOT NULL,pages integer NOT NULL,categories integer NOT NULL,markets integer NOT NULL,new_markets integer NOT NULL,candidates integer NOT NULL,filtered_markets integer NOT NULL,page_limit_reached boolean NOT NULL DEFAULT false,error text);
CREATE TABLE IF NOT EXISTS predict_market_meta(meta_key text PRIMARY KEY,meta_value text NOT NULL);
"""
CHECKSUM=hashlib.sha256(SCHEMA_SQL.encode()).hexdigest()
TIMESTAMP_CHECKSUM=hashlib.sha256(b"predict market UTC timestamp indexes v2").hexdigest()

def _parse(value):
    if not value:return None
    try:r=datetime.fromisoformat(value.replace('Z','+00:00'))
    except ValueError:return None
    return r.replace(tzinfo=UTC) if r.tzinfo is None else r.astimezone(UTC)
def _iso(value):return value.astimezone(UTC).isoformat(timespec='microseconds')

class PostgresPredictMarketStore:
    def __init__(self,path,*,initialize=True):self.path=path;self.initialize() if initialize else None
    @staticmethod
    def initialize_schema():
        def timestamps(conn):
            conn.execute("ALTER TABLE predict_market_observations ADD COLUMN IF NOT EXISTS starts_at_utc timestamptz")
            conn.execute("ALTER TABLE predict_market_observations ADD COLUMN IF NOT EXISTS market_created_at_utc timestamptz")
            rows=conn.execute("SELECT market_id,starts_at,market_created_at FROM predict_market_observations WHERE starts_at_utc IS NULL OR market_created_at_utc IS NULL").fetchall()
            for row in rows:
                conn.execute("UPDATE predict_market_observations SET starts_at_utc=%s,market_created_at_utc=%s WHERE market_id=%s",(_parse(row['starts_at']),_parse(row['market_created_at']),row['market_id']))
            conn.execute("CREATE INDEX IF NOT EXISTS idx_predict_market_candidate_window ON predict_market_observations(candidate_at,starts_at_utc,market_created_at_utc) WHERE filter_reason IS NULL")
        with connect_postgres(schema='predict_market',application_name='odaily-predict-migrate') as c:apply_schema_migrations(c,schema='predict_market',component='predict_market',migrations=(PostgresMigration(1,'predict market persistence',CHECKSUM,lambda x:x.execute(SCHEMA_SQL)),PostgresMigration(2,'predict market UTC timestamp indexes',TIMESTAMP_CHECKSUM,timestamps)))
    def initialize(self):self.initialize_schema()
    def is_bootstrapped(self):
        with connect_postgres(schema='predict_market',application_name='odaily-predict') as c:return c.execute("SELECT 1 FROM predict_market_meta WHERE meta_key='bootstrapped_at'").fetchone() is not None
    def record_scan(self,*,observations:list[MarketObservation],pages:int,categories:int,started_at:datetime,page_limit_reached:bool)->dict[str,Any]:
        completed=datetime.now(UTC);now=_iso(completed);dedup={o.market_id:o for o in observations};new=filtered=0;lower=completed-timedelta(hours=72);upper=completed+timedelta(hours=72);created_lower=completed-timedelta(hours=72)
        with connect_postgres(schema='predict_market',application_name='odaily-predict-scan') as c:
            with c.transaction():
                c.execute("SELECT pg_advisory_xact_lock(hashtextextended('predict-market-bootstrap',0))")
                baseline=c.execute("SELECT 1 FROM predict_market_meta WHERE meta_key='bootstrapped_at'").fetchone() is None
                for o in dedup.values():
                    exists=c.execute('SELECT 1 FROM predict_market_observations WHERE market_id=%s',(o.market_id,)).fetchone();fresh=exists is None;new+=int(fresh and not baseline);filtered+=int(o.filter_reason is not None)
                    c.execute("""INSERT INTO predict_market_observations(market_id,category_id,category_title,category_slug,category_published_at,starts_at,ends_at,market_created_at,question,market_variant,market_status,trading_status,market_url,filter_reason,first_seen_at,last_seen_at,from_baseline,candidate_at,starts_at_utc,market_created_at_utc) VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,NULL,%s,%s) ON CONFLICT(market_id) DO UPDATE SET category_id=excluded.category_id,category_title=excluded.category_title,category_slug=excluded.category_slug,category_published_at=excluded.category_published_at,starts_at=excluded.starts_at,ends_at=excluded.ends_at,market_created_at=excluded.market_created_at,question=excluded.question,market_variant=excluded.market_variant,market_status=excluded.market_status,trading_status=excluded.trading_status,market_url=excluded.market_url,filter_reason=excluded.filter_reason,last_seen_at=excluded.last_seen_at,starts_at_utc=excluded.starts_at_utc,market_created_at_utc=excluded.market_created_at_utc""",(o.market_id,o.category_id,o.category_title,o.category_slug,o.category_published_at,o.starts_at,o.ends_at,o.market_created_at,o.question,o.market_variant,o.market_status,o.trading_status,o.market_url,o.filter_reason,now,now,baseline,_parse(o.starts_at),_parse(o.market_created_at)))
                if baseline:c.execute("INSERT INTO predict_market_meta VALUES('bootstrapped_at',%s) ON CONFLICT(meta_key) DO NOTHING",(now,))
                rows=c.execute('SELECT market_id,starts_at_utc,market_created_at_utc,trading_status FROM predict_market_observations WHERE candidate_at IS NULL AND starts_at_utc IS NOT NULL AND market_created_at_utc IS NOT NULL').fetchall()
                for r in rows:
                    start=r['starts_at_utc'];created_at=r['market_created_at_utc']
                    if start and lower<=start<=upper and created_at and created_lower<=created_at<=completed and str(r['trading_status']).upper()=='OPEN':c.execute('UPDATE predict_market_observations SET candidate_at=%s WHERE market_id=%s',(now,r['market_id']))
                candidate_count=int(c.execute("SELECT count(*) n FROM predict_market_observations WHERE candidate_at IS NOT NULL AND filter_reason IS NULL AND starts_at_utc BETWEEN %s AND %s AND market_created_at_utc BETWEEN %s AND %s AND trading_status='OPEN'",(lower,upper,created_lower,completed)).fetchone()['n'])
                c.execute('INSERT INTO predict_market_scan_runs(started_at,completed_at,status,pages,categories,markets,new_markets,candidates,filtered_markets,page_limit_reached) VALUES(%s,%s,\'success\',%s,%s,%s,%s,%s,%s,%s)',(_iso(started_at),now,pages,categories,len(dedup),new,candidate_count,filtered,page_limit_reached))
                rows=c.execute("SELECT market_id,question,category_title,category_slug,category_published_at,starts_at,market_created_at,market_variant,market_status,trading_status,market_url,first_seen_at,from_baseline,candidate_at FROM predict_market_observations WHERE candidate_at=%s AND filter_reason IS NULL AND starts_at_utc BETWEEN %s AND %s AND market_created_at_utc BETWEEN %s AND %s AND trading_status='OPEN' ORDER BY market_created_at_utc DESC,market_id LIMIT 30",(now,lower,upper,created_lower,completed)).fetchall();items=[dict(r) for r in rows]
        return {'baseline':baseline,'pages':pages,'categories':categories,'markets':len(dedup),'new_markets':new,'new_candidates':len(items),'pending_candidates':candidate_count,'filtered_markets':filtered,'page_limit_reached':page_limit_reached,'candidate_items':items}
    def record_failure(self,*,started_at,error):
        now=datetime.now(UTC)
        with connect_postgres(schema='predict_market',application_name='odaily-predict-scan') as c:c.execute("INSERT INTO predict_market_scan_runs(started_at,completed_at,status,pages,categories,markets,new_markets,candidates,filtered_markets,page_limit_reached,error) VALUES(%s,%s,'failed',0,0,0,0,0,0,false,%s)",(_iso(started_at),_iso(now),error[:1000]))
    def dashboard(self,*,candidate_limit=50):
        now=datetime.now(UTC);lower=now-timedelta(hours=72);upper=now+timedelta(hours=72);created=now-timedelta(hours=72)
        with connect_postgres(schema='predict_market',application_name='odaily-predict-dashboard') as c:
            total=int(c.execute('SELECT count(*) n FROM predict_market_observations').fetchone()['n']);filtered=int(c.execute('SELECT count(*) n FROM predict_market_observations WHERE filter_reason IS NOT NULL').fetchone()['n']);pending=int(c.execute("SELECT count(*) n FROM predict_market_observations WHERE candidate_at IS NOT NULL AND filter_reason IS NULL AND starts_at_utc BETWEEN %s AND %s AND market_created_at_utc BETWEEN %s AND %s AND trading_status='OPEN'",(lower,upper,created,now)).fetchone()['n']);items=[dict(r) for r in c.execute("SELECT market_id,question,category_title,category_slug,category_published_at,starts_at,market_created_at,market_variant,market_status,trading_status,market_url,first_seen_at,from_baseline,candidate_at FROM predict_market_observations WHERE candidate_at IS NOT NULL AND filter_reason IS NULL AND starts_at_utc BETWEEN %s AND %s AND market_created_at_utc BETWEEN %s AND %s AND trading_status='OPEN' ORDER BY market_created_at_utc DESC LIMIT %s",(lower,upper,created,now,candidate_limit)).fetchall()];scan=c.execute('SELECT * FROM predict_market_scan_runs ORDER BY id DESC LIMIT 1').fetchone();boot=c.execute("SELECT meta_value FROM predict_market_meta WHERE meta_key='bootstrapped_at'").fetchone()
        return {'database_path':f'postgres:{self.path}','bootstrapped_at':boot['meta_value'] if boot else None,'seen_markets':total,'pending_candidates':pending,'filtered_markets':filtered,'last_scan':dict(scan) if scan else None,'candidates':items}

__all__=['PostgresPredictMarketStore','SCHEMA_SQL']
